<script setup>
import { computed, ref } from "vue";
import { Search, SlidersHorizontal, LayoutGrid, List, ArrowUpRight, X } from "lucide-vue-next";
import { productSeed } from "../commerce/data.js";
import ProductArt from "../commerce/ProductArt.vue";
const props = defineProps({ page: { type: String, required: true } });
const query = ref("canvas"), category = ref("All categories");
const view = computed(() => props.page === "Search list" ? "list" : "grid");
const categories = computed(() => ["All categories", ...new Set(productSeed.map(p => p.category))]);
const results = computed(() => productSeed.filter(p => (!query.value.trim() || `${p.name} ${p.sku} ${p.category} ${p.description}`.toLowerCase().includes(query.value.trim().toLowerCase())) && (category.value === "All categories" || p.category === category.value)));
const money = value => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(value);
</script>
<template>
  <section class="search-results-view" aria-labelledby="search-results-title">
    <header class="results-heading"><div><span class="results-kicker">STORE / DISCOVERY</span><h2 id="search-results-title">Search results</h2><p>Find the right product across your catalog.</p></div><span class="results-count">{{ results.length }} products found</span></header>
    <div class="results-search-panel">
      <label class="results-searchbox"><Search :size="19" aria-hidden="true" /><span class="sr-only">Search products</span><input v-model="query" placeholder="Search products, categories, or SKU" /><button v-if="query" type="button" aria-label="Clear search" @click="query = ''"><X :size="17" /></button></label>
      <label class="category-filter"><SlidersHorizontal :size="17" aria-hidden="true" /><span class="sr-only">Filter by category</span><select v-model="category"><option v-for="item in categories" :key="item">{{ item }}</option></select></label>
      <div class="view-toggle" aria-label="Result layout"><span>View</span><a href="#Search grid" :class="{ active: view === 'grid' }" aria-label="Grid view"><LayoutGrid :size="17" /></a><a href="#Search list" :class="{ active: view === 'list' }" aria-label="List view"><List :size="18" /></a></div>
    </div>
    <div v-if="results.length" class="product-results" :class="`results-${view}`">
      <article v-for="product in results" :key="product.id" class="result-card">
        <div class="result-art"><ProductArt :product="product" /><span :class="['product-status', product.status.toLowerCase()]">{{ product.status }}</span></div>
        <div class="result-info"><div class="result-category">{{ product.category }} <span>·</span> {{ product.sku }}</div><h3>{{ product.name }}</h3><p>{{ product.description }}</p><div class="result-meta"><strong>{{ money(product.price) }}</strong><span>{{ product.stock }} in stock</span></div></div>
        <button class="result-open" :aria-label="`View ${product.name}`"><ArrowUpRight :size="17" /></button>
      </article>
    </div>
    <div v-else class="results-empty"><Search :size="24" /><h3>No products found</h3><p>Try another search term or choose a different category.</p><button type="button" @click="query = ''; category = 'All categories'">Clear filters</button></div>
    <footer v-if="results.length" class="results-footer">Showing {{ results.length }} of {{ productSeed.length }} products <span>Updated just now</span></footer>
  </section>
</template>
<style scoped>
